// C1.1 — Linux, terminal e sistemas operacionais: exercícios (por aula), prova final e projeto integrador.
// Os desafios "code" usam JavaScript (única linguagem executável no laboratório) para modelar a lógica de comandos do Linux.
const R = String.raw;

export const exsets = {
'lnx-01': [
  { id: 'lnx-01-e1', type: 'mc', difficulty: 1, points: 10, prompt: 'Na saída de §ls -l§, a linha começa com §lrwxrwxrwx§. O que o primeiro caractere §l§ indica?', options: ['Que o arquivo está bloqueado (locked) para escrita', 'Que o arquivo é um diretório de logs', 'Que o item é um link simbólico', 'Que o arquivo está em uso por outro processo'], answer: 2, explanation: 'O primeiro caractere é o tipo: §-§ arquivo comum, §d§ diretório e §l§ link simbólico. As letras seguintes são as permissões, que em links simbólicos costumam aparecer como §rwxrwxrwx§ e não controlam o acesso ao alvo.' },
  { id: 'lnx-01-e2', type: 'tf', difficulty: 2, points: 5, prompt: 'Existe um arquivo §dados.txt§ e um hard link §copia.txt§ para ele. Se você apagar §dados.txt§ com §rm§, o conteúdo continua acessível por §copia.txt§.', answer: true, explanation: 'Um hard link é outro nome para o mesmo inode. Os dados só são liberados quando o contador de links chega a zero e nenhum processo mantém o arquivo aberto. Com um link simbólico, o resultado seria diferente: o link ficaria quebrado.' },
  { id: 'lnx-01-e3', type: 'match', difficulty: 1, points: 10, prompt: 'Associe cada diretório ao seu uso típico.', pairs: [['/etc', 'Arquivos de configuração do sistema'], ['/var/log', 'Logs de serviços e do sistema'], ['/proc', 'Visão do kernel sobre processos e memória (não fica em disco)'], ['/tmp', 'Arquivos temporários de qualquer usuário']], explanation: 'A convenção do FHS facilita encontrar tudo: configuração em §/etc§, dados variáveis como logs em §/var§, pseudo-arquivos do kernel em §/proc§ e temporários em §/tmp§.' },
  { id: 'lnx-01-e4', type: 'fill', difficulty: 1, points: 10, prompt: 'Complete os comandos: criar a cadeia de diretórios sem erro se já existir e criar um link simbólico.', code: 'mkdir [[0]] relatorios/2026/novembro\nln [[1]] ../dados/vendas.csv atalho.csv', answers: [['-p'], ['-s']], explanation: '§mkdir -p§ cria os diretórios intermediários e não reclama se já existirem. §ln -s alvo atalho§ cria um link simbólico; sem §-s§, o §ln§ cria um hard link.' },
  { id: 'lnx-01-e5', type: 'code', difficulty: 2, points: 20, prompt: 'Implemente §resolverCaminho(cwd, caminho)§, que devolve o caminho **absoluto normalizado**, como o kernel resolveria. Se §caminho§ começa com §/§, parta da raiz; senão, parta de §cwd§. Ignore componentes vazios (barras repetidas) e §.§; trate §..§ subindo um nível (na raiz, §..§ continua na raiz). Não use §~§. O resultado nunca termina em §/§, exceto a própria raiz §"/"§.', lang: 'javascript', starter: 'function resolverCaminho(cwd, caminho) {\n  // seu código aqui\n}\n', hints: ['Divida o caminho completo por "/" e use uma pilha de nomes.', '".." remove o último nome da pilha (se houver); "." e "" são ignorados.'], tests: [{ name: 'relativo com . e ..', code: "assert.equal(resolverCaminho('/home/ana', 'src/../docs/./a.txt'), '/home/ana/docs/a.txt');" }, { name: 'absoluto ignora o cwd e barras repetidas', code: "assert.equal(resolverCaminho('/x', '/etc//passwd'), '/etc/passwd');" }, { name: '.. na raiz continua na raiz', code: "assert.equal(resolverCaminho('/a/b', '../../..'), '/'); assert.equal(resolverCaminho('/', '..'), '/');" }, { name: 'caminho vazio ou . devolve o cwd', code: "assert.equal(resolverCaminho('/var/log', '.'), '/var/log'); assert.equal(resolverCaminho('/var/log', ''), '/var/log');" }, { name: 'sem barra final', code: "assert.equal(resolverCaminho('/a', 'b/c/'), '/a/b/c');" }], solution: "function resolverCaminho(cwd, caminho) {\n  const completo = caminho.startsWith('/') ? caminho : cwd + '/' + caminho;\n  const pilha = [];\n  for (const parte of completo.split('/')) {\n    if (parte === '' || parte === '.') continue;\n    if (parte === '..') { pilha.pop(); continue; }\n    pilha.push(parte);\n  }\n  return '/' + pilha.join('/');\n}\n", explanation: 'O kernel resolve o caminho componente por componente. Uma pilha de nomes modela isso: nomes entram, §..§ remove o último, §.§ e componentes vazios são ignorados. Na raiz, §pop§ em uma pilha vazia não faz nada, o que reproduz o comportamento de §/..§ = §/§.' }
],
'lnx-02': [
  { id: 'lnx-02-e1', type: 'mc', difficulty: 2, points: 10, prompt: 'O que acontece ao executar §sort dados.txt > dados.txt§?', options: ['O arquivo é ordenado com sucesso', 'O arquivo fica vazio, porque o shell o trunca antes de o sort lê-lo', 'O comando falha com erro de sintaxe', 'O arquivo original é copiado para dados.txt.bak'], answer: 1, explanation: 'O shell abre o destino do redirecionamento (truncando-o) **antes** de iniciar o §sort§, que então lê um arquivo já vazio. Para ordenar "no lugar", escreva em um temporário e use §mv§ (ou o §sort -o§ do GNU, que trata isso).' },
  { id: 'lnx-02-e2', type: 'trace', difficulty: 2, points: 10, prompt: 'Rastreie os comandos (o arquivo §/etc/hostname§ não contém a palavra "zzz").', code: "printf 'b\\na\\nb\\n' | sort | uniq -c\necho $?\ngrep -q zzz /etc/hostname; echo $?", lang: 'bash', steps: [{ q: 'Quantas vezes o valor §b§ aparece, segundo o contador do §uniq -c§?', answers: ['2'] }, { q: 'O que o primeiro §echo $?§ imprime?', answers: ['0'] }, { q: 'O que o segundo §echo $?§ imprime?', answers: ['1'] }], explanation: '§sort§ agrupa as linhas e §uniq -c§ mostra "2 b" e "1 a". O pipeline terminou com sucesso (§0§, o código do último comando). O §grep -q§ não achou "zzz" e sai com §1§ (não achou); §2§ seria erro real.' },
  { id: 'lnx-02-e3', type: 'bug', difficulty: 2, points: 10, prompt: 'O objetivo é gravar **saída e erros** do build em §build.log§, mas as mensagens de erro continuam aparecendo no terminal. Clique na linha com o problema.', code: '#!/usr/bin/env bash\nset -u\n./build.sh 2>&1 > build.log\necho "fim do build"', answer: 3, explanation: 'A ordem importa: §2>&1§ faz o fd 2 apontar para onde o fd 1 está **naquele momento** (o terminal); só depois o §> build.log§ redireciona o fd 1. O correto é §./build.sh > build.log 2>&1§.' },
  { id: 'lnx-02-e4', type: 'tf', difficulty: 1, points: 5, prompt: 'Quando o §grep§ não encontra nenhuma linha que case com o padrão, ele termina com código de saída 2 (erro).', answer: false, explanation: 'O §grep§ sai com §0§ se achou, §1§ se **não achou** (situação normal) e §2§ em erro real, como arquivo inexistente. Scripts devem distinguir 1 de 2.' },
  { id: 'lnx-02-e5', type: 'code', difficulty: 2, points: 20, prompt: 'Implemente §contarFrequencias(linhas)§, que reproduz §sort | uniq -c | sort -rn§. Receba um array de strings e devolva um array de §{ linha, vezes }§ ordenado por §vezes§ **decrescente**; em empate, por §linha§ em ordem alfabética crescente (comparação simples de strings).', lang: 'javascript', starter: 'function contarFrequencias(linhas) {\n  // seu código aqui\n}\n', hints: ['Conte com um Map ou objeto.', 'No sort, compare primeiro b.vezes - a.vezes; em empate compare as strings com < e >.'], tests: [{ name: 'conta e ordena', code: "assert.deepEqual(contarFrequencias(['b','a','b','c','a','b']), [{linha:'b',vezes:3},{linha:'a',vezes:2},{linha:'c',vezes:1}]);" }, { name: 'desempate alfabético', code: "assert.deepEqual(contarFrequencias(['y','x']), [{linha:'x',vezes:1},{linha:'y',vezes:1}]);" }, { name: 'entrada vazia', code: 'assert.deepEqual(contarFrequencias([]), []);' }, { name: 'não altera o array de entrada', code: "const e = ['b','a']; contarFrequencias(e); assert.deepEqual(e, ['b','a']);" }], solution: "function contarFrequencias(linhas) {\n  const mapa = new Map();\n  for (const l of linhas) mapa.set(l, (mapa.get(l) || 0) + 1);\n  return [...mapa].map(([linha, vezes]) => ({ linha, vezes })).sort((a, b) => b.vezes - a.vezes || (a.linha < b.linha ? -1 : a.linha > b.linha ? 1 : 0));\n}\n", explanation: 'O pipeline Unix é uma composição de transformações: agrupar (sort), contar (uniq -c) e reordenar (sort -rn). Em código, isso vira contagem em um Map seguida de ordenação com critério de desempate, o que torna o resultado determinístico.' },
  { id: 'lnx-02-e6', type: 'open', difficulty: 2, points: 10, prompt: 'Um arquivo §access.log§ tem o IP do cliente na primeira coluna (separada por espaço). Escreva o pipeline que mostra os **3 IPs mais frequentes** e explique cada etapa.', model: "cut -d' ' -f1 access.log | sort | uniq -c | sort -rn | head -3. O cut extrai a primeira coluna (IP); o sort agrupa IPs iguais; o uniq -c conta cada grupo; o sort -rn ordena do maior para o menor contador; o head -3 mantém os três primeiros.", rubric: ['Extrai a coluna do IP (cut ou awk)', 'Usa sort antes de uniq -c para agrupar', 'Ordena por contagem decrescente (sort -rn)', 'Limita a três resultados (head -3)'], explanation: 'O objetivo é treinar a composição de comandos. Variações válidas incluem §awk \'{print $1}\'§ no lugar do §cut§.' }
],
'lnx-03': [
  { id: 'lnx-03-e1', type: 'mc', difficulty: 1, points: 10, prompt: 'Qual é o modo octal equivalente a §rwxr-x---§?', options: ['755', '750', '570', '640'], answer: 1, explanation: 'Dono §rwx§ = 4+2+1 = 7; grupo §r-x§ = 4+0+1 = 5; outros §---§ = 0. Resultado: 750. O 755 daria leitura e execução para todos.' },
  { id: 'lnx-03-e2', type: 'tf', difficulty: 2, points: 5, prompt: 'Para apagar um arquivo basta ter permissão de escrita (§w§) **no próprio arquivo**.', answer: false, explanation: 'Apagar é alterar o diretório que contém o nome do arquivo. A permissão necessária é §w§ **e** §x§ no diretório. O sticky bit (como em §/tmp§) restringe ainda mais: só o dono do arquivo pode apagá-lo.' },
  { id: 'lnx-03-e3', type: 'fill', difficulty: 1, points: 10, prompt: 'Proteja a chave SSH: só o dono lê e escreve a chave; só o dono acessa a pasta.', code: 'chmod [[0]] ~/.ssh/id_ed25519\nchmod [[1]] ~/.ssh', answers: [['600'], ['700']], explanation: '600 é §rw-------§ (o cliente SSH recusa chaves privadas legíveis por outros) e 700 é §rwx------§ para a pasta, de modo que só o dono a atravessa.' },
  { id: 'lnx-03-e4', type: 'mc', difficulty: 2, points: 10, prompt: 'O arquivo tem modo §-rw-r-----§, dono §bruno§ e grupo §dev§. Ana pertence ao grupo §dev§; Carla não. Quem consegue ler o conteúdo (sem sudo)?', options: ['Somente Bruno', 'Bruno e Ana', 'Bruno, Ana e Carla', 'Ninguém além do root'], answer: 1, explanation: 'O kernel usa a primeira classe que se aplica: Bruno é o dono (§rw-§), Ana está no grupo (§r--§) e Carla cai em "outros" (§---§). Carla não lê.' },
  { id: 'lnx-03-e5', type: 'code', difficulty: 2, points: 20, prompt: 'Implemente §octalParaSimbolico(modo)§, que recebe uma string de **três dígitos octais** (ex.: §"640"§) e devolve as nove letras (§"rw-r-----"§). Se a entrada não tiver exatamente três dígitos de 0 a 7, lance um §Error§ com a mensagem §"modo inválido"§.', lang: 'javascript', starter: 'function octalParaSimbolico(modo) {\n  // seu código aqui\n}\n', hints: ['Valide com uma regex como /^[0-7]{3}$/.', 'Para cada dígito, teste os bits 4, 2 e 1.'], tests: [{ name: '755', code: "assert.equal(octalParaSimbolico('755'), 'rwxr-xr-x');" }, { name: '640 e 000', code: "assert.equal(octalParaSimbolico('640'), 'rw-r-----'); assert.equal(octalParaSimbolico('000'), '---------');" }, { name: '777', code: "assert.equal(octalParaSimbolico('777'), 'rwxrwxrwx');" }, { name: 'entrada inválida lança erro', code: "assert.throws(() => octalParaSimbolico('999'), 'modo inválido'); assert.throws(() => octalParaSimbolico('64'), 'modo inválido'); assert.throws(() => octalParaSimbolico('6400'), 'modo inválido');" }], solution: "function octalParaSimbolico(modo) {\n  if (!/^[0-7]{3}$/.test(String(modo))) throw new Error('modo inválido');\n  return [...String(modo)].map((d) => {\n    const n = Number(d);\n    return (n & 4 ? 'r' : '-') + (n & 2 ? 'w' : '-') + (n & 1 ? 'x' : '-');\n  }).join('');\n}\n", explanation: 'Cada dígito octal soma os bits r=4, w=2 e x=1. Um teste bit a bit (§&§) converte o número em letras. Validar a entrada antes de converter evita resultados enganosos como "999".' }
],
'lnx-04': [
  { id: 'lnx-04-e1', type: 'mc', difficulty: 2, points: 10, prompt: 'Um contêiner reinicia sozinho e o orquestrador mostra §exit code 137§. O que isso indica?', options: ['O programa terminou normalmente com o código 137 definido pelo desenvolvedor', 'O processo foi morto por SIGKILL (128 + 9), frequentemente pelo OOM killer ou por um limite de recursos', 'O processo recebeu SIGTERM e fez um encerramento limpo', 'O contêiner perdeu a conexão de rede'], answer: 1, explanation: 'Por convenção do shell, morte por sinal gera 128 + número do sinal. 137 = 128 + 9 (SIGKILL). Um encerramento limpo por SIGTERM geraria 143. O próximo passo é conferir o log do kernel e o limite de memória.' },
  { id: 'lnx-04-e2', type: 'match', difficulty: 1, points: 10, prompt: 'Associe cada sinal ao seu efeito.', pairs: [['SIGTERM', 'Pedido educado de término; o programa pode tratá-lo e limpar recursos'], ['SIGKILL', 'Término forçado; não pode ser capturado nem ignorado'], ['SIGINT', 'Interrupção enviada pelo Ctrl+C'], ['SIGSTOP', 'Pausa o processo; não pode ser capturado']], explanation: 'SIGTERM (15) é o padrão do §kill§ e permite encerramento gracioso. SIGKILL (9) e SIGSTOP não podem ser capturados. SIGINT (2) vem do teclado.' },
  { id: 'lnx-04-e3', type: 'tf', difficulty: 2, points: 5, prompt: 'Um processo zumbi (estado §Z§) pode ser eliminado com §kill -9§ no PID do zumbi.', answer: false, explanation: 'O zumbi já terminou; só resta a entrada na tabela de processos, que o **pai** deve liberar com §wait§. A solução é corrigir ou reiniciar o pai (ou o PID 1 adota e limpa quando o pai morre).' },
  { id: 'lnx-04-e4', type: 'trace', difficulty: 2, points: 10, prompt: 'Rastreie o script.', code: 'sleep 100 &\nkill -9 $!\nwait $!\necho $?\nsleep 100 &\nkill $!\nwait $!\necho $?', lang: 'bash', steps: [{ q: 'O que o primeiro §echo $?§ imprime?', answers: ['137'] }, { q: 'O que o segundo §echo $?§ imprime?', answers: ['143'] }], explanation: '§$!§ é o PID do último job em segundo plano. §wait§ devolve o código de saída do processo. Morto por SIGKILL (9): 128+9 = 137. §kill§ sem opção envia SIGTERM (15): 128+15 = 143.' },
  { id: 'lnx-04-e5', type: 'code', difficulty: 2, points: 20, prompt: 'Implemente §descreverSaida(codigo)§. Regras: §0§ devolve §"sucesso"§; códigos de §1§ a §128§ e de §160§ a §255§ devolvem §"erro (código N)"§; códigos de §129§ a §159§ representam morte por sinal §N-128§ e devolvem §"morto por SIGNOME (n)"§ para os sinais conhecidos (§1§ SIGHUP, §2§ SIGINT, §9§ SIGKILL, §15§ SIGTERM) ou §"morto pelo sinal n"§ para os demais. Lance §Error§ se o código não for um inteiro entre 0 e 255.', lang: 'javascript', starter: 'function descreverSaida(codigo) {\n  // seu código aqui\n}\n', hints: ['Valide primeiro: Number.isInteger e intervalo 0..255.', 'Para 129..159 faça n = codigo - 128 e consulte um objeto de nomes.'], tests: [{ name: 'sucesso e erro comum', code: "assert.equal(descreverSaida(0), 'sucesso'); assert.equal(descreverSaida(2), 'erro (código 2)'); assert.equal(descreverSaida(128), 'erro (código 128)');" }, { name: 'sinais conhecidos', code: "assert.equal(descreverSaida(137), 'morto por SIGKILL (9)'); assert.equal(descreverSaida(143), 'morto por SIGTERM (15)'); assert.equal(descreverSaida(130), 'morto por SIGINT (2)'); assert.equal(descreverSaida(129), 'morto por SIGHUP (1)');" }, { name: 'sinal desconhecido', code: "assert.equal(descreverSaida(140), 'morto pelo sinal 12');" }, { name: 'fora da faixa de sinais', code: "assert.equal(descreverSaida(160), 'erro (código 160)'); assert.equal(descreverSaida(255), 'erro (código 255)');" }, { name: 'entrada inválida', code: 'assert.throws(() => descreverSaida(-1)); assert.throws(() => descreverSaida(256)); assert.throws(() => descreverSaida(1.5)); assert.throws(() => descreverSaida("9"));' }], solution: "function descreverSaida(codigo) {\n  if (!Number.isInteger(codigo) || codigo < 0 || codigo > 255) throw new Error('código inválido');\n  if (codigo === 0) return 'sucesso';\n  if (codigo >= 129 && codigo <= 159) {\n    const n = codigo - 128;\n    const nomes = { 1: 'SIGHUP', 2: 'SIGINT', 9: 'SIGKILL', 15: 'SIGTERM' };\n    return nomes[n] ? 'morto por ' + nomes[n] + ' (' + n + ')' : 'morto pelo sinal ' + n;\n  }\n  return 'erro (código ' + codigo + ')';\n}\n", explanation: 'A convenção 128 + n permite ler um código de saída como "morte por sinal" sem perguntar ao sistema. O intervalo foi limitado a 129..159 para manter o exercício determinístico; nos sistemas reais, outros códigos de erro (como 126, 127 e 255) têm significados próprios.' },
  { id: 'lnx-04-e6', type: 'mc', difficulty: 2, points: 10, prompt: 'Duas threads do **mesmo processo** compartilham:', options: ['A pilha de chamadas e os registradores', 'O espaço de endereçamento (memória) e os descritores de arquivos', 'Apenas o PID, mas cada uma tem memória própria', 'Nada: threads são isoladas como processos'], answer: 1, explanation: 'Threads compartilham memória e descritores do processo; cada thread tem a **própria pilha** e registradores. É por isso que são baratas, mas exigem sincronização para evitar condições de corrida.' }
],
'lnx-05': [
  { id: 'lnx-05-e1', type: 'mc', difficulty: 2, points: 10, prompt: 'No §free -h§ de um servidor de produção, a coluna §free§ mostra 120 MB e §available§ mostra 9 GB. O que concluir?', options: ['Há risco iminente de OOM: é preciso reiniciar serviços', 'O sistema está saudável: a maior parte da RAM está em cache, que é liberado sob demanda', 'O swap está sendo usado intensamente', 'A memória física está com defeito'], answer: 1, explanation: 'O kernel usa a RAM ociosa como cache de arquivos (buff/cache). Esse cache é descartado quando programas precisam de memória, e a coluna §available§ já o inclui. O que importa é §available§, não §free§.' },
  { id: 'lnx-05-e2', type: 'tf', difficulty: 2, points: 5, prompt: 'Se o VSZ de um processo é muito maior que o seu RSS, isso comprova que o programa tem um vazamento de memória.', answer: false, explanation: 'VSZ conta endereços virtuais mapeados (alocação preguiçosa, bibliotecas, mapeamentos), e é normalmente muito maior que a RAM realmente usada (RSS). Vazamento se evidencia pelo **RSS crescendo ao longo do tempo**.' },
  { id: 'lnx-05-e3', type: 'fill', difficulty: 1, points: 10, prompt: 'Complete os comandos de diagnóstico de memória e de limites.', code: 'free -h        # olhe a coluna [[0]]\nulimit -[[1]]  # limite de arquivos abertos do shell', answers: [['available'], ['n']], explanation: 'A coluna §available§ estima a memória disponível sem swap, incluindo cache descartável. §ulimit -n§ mostra (e define) o limite de descritores abertos.' },
  { id: 'lnx-05-e4', type: 'mc', difficulty: 3, points: 10, prompt: 'Um contêiner com limite de 512 MB é encerrado com código 137 em um servidor com 64 GB de RAM livres. Qual a explicação mais provável?', options: ['O servidor está sem memória física', 'O cgroup do contêiner atingiu o limite e o OOM killer atuou dentro do grupo', 'O kernel não suporta contêineres com mais de 100 MB', 'O swap foi desativado globalmente'], answer: 1, explanation: 'Limites de memória de contêineres são aplicados por cgroups. Ao ultrapassar o teto do grupo, o OOM killer mata um processo **do grupo**, mesmo com RAM sobrando no host. Investigue o consumo e dimensione o limite com dados.' },
  { id: 'lnx-05-e5', type: 'code', difficulty: 2, points: 20, prompt: 'Implemente §memoriaDisponivel(meminfo)§. O parâmetro é o texto de §/proc/meminfo§ (linhas como §"MemTotal:        8388608 kB"§). Devolva §{ totalMiB, disponivelMiB, pctDisponivel }§, com os valores em MiB (kB ÷ 1024, arredondado com §Math.round§) e o percentual §Math.round(100 × MemAvailable / MemTotal)§. Se faltar §MemTotal§ ou §MemAvailable§, lance §Error§ com a mensagem §"campo ausente"§.', lang: 'javascript', starter: 'function memoriaDisponivel(meminfo) {\n  // seu código aqui\n}\n', hints: ['Quebre o texto em linhas e use uma regex como /^(\\w+):\\s+(\\d+)\\s*kB/.', 'Guarde os campos em um objeto antes de calcular.'], tests: [{ name: 'calcula MiB e percentual', code: "const t = 'MemTotal:        8388608 kB\\nMemFree:          100000 kB\\nMemAvailable:    2097152 kB\\nSwapTotal:             0 kB';\nassert.deepEqual(memoriaDisponivel(t), { totalMiB: 8192, disponivelMiB: 2048, pctDisponivel: 25 });" }, { name: 'arredondamento', code: "const t = 'MemTotal: 3000000 kB\\nMemAvailable: 1000000 kB';\nconst r = memoriaDisponivel(t); assert.equal(r.totalMiB, 2930); assert.equal(r.disponivelMiB, 977); assert.equal(r.pctDisponivel, 33);" }, { name: 'campo ausente', code: "assert.throws(() => memoriaDisponivel('MemTotal: 100 kB'), 'campo ausente'); assert.throws(() => memoriaDisponivel('MemAvailable: 100 kB'), 'campo ausente');" }], solution: "function memoriaDisponivel(meminfo) {\n  const c = {};\n  for (const linha of meminfo.split('\\n')) {\n    const m = /^(\\w+):\\s+(\\d+)\\s*kB/.exec(linha.trim());\n    if (m) c[m[1]] = Number(m[2]);\n  }\n  if (c.MemTotal == null || c.MemAvailable == null) throw new Error('campo ausente');\n  return { totalMiB: Math.round(c.MemTotal / 1024), disponivelMiB: Math.round(c.MemAvailable / 1024), pctDisponivel: Math.round((100 * c.MemAvailable) / c.MemTotal) };\n}\n", explanation: 'Os painéis de monitoramento fazem exatamente isto: leem §/proc/meminfo§ e usam §MemAvailable§, não §MemFree§, para calcular a memória disponível e disparar alertas.' },
  { id: 'lnx-05-e6', type: 'open', difficulty: 3, points: 15, prompt: 'Um serviço Node.js em contêiner reinicia a cada algumas horas, sem exceção nos logs da aplicação. Descreva como você investigaria a hipótese de falta de memória e quais medidas tomaria.', model: 'Verificar o código de saída do contêiner (137 sugere SIGKILL); consultar o log do kernel (journalctl -k ou dmesg) por "Out of memory"; ver o limite de memória do contêiner/cgroup e comparar com o RSS do processo ao longo do tempo (ps -o rss, métricas); checar se o RSS cresce linearmente (vazamento) ou tem picos de carga; usar profiler/heap snapshot para achar o vazamento; medidas: corrigir o vazamento, ajustar o limite com margem baseada em medições, criar alertas de memória e de reinícios.', rubric: ['Reconhece o código 137/SIGKILL e o OOM killer como hipótese', 'Cita o log do kernel como evidência', 'Compara o RSS/limite do cgroup ao longo do tempo', 'Propõe corrigir o consumo/vazamento e dimensionar o limite com dados', 'Menciona alertas ou monitoramento'], explanation: 'Resposta forte combina evidência (código, log do kernel), medição (RSS no tempo) e correção da causa, não apenas aumento do limite.' }
],
'lnx-06': [
  { id: 'lnx-06-e1', type: 'mc', difficulty: 2, points: 10, prompt: 'O que faz o redirecionamento §2>&1§ em §cmd > saida.txt 2>&1§?', options: ['Envia os erros (fd 2) para o mesmo destino da saída padrão (fd 1)', 'Duplica o arquivo saida.txt', 'Faz o programa ler a entrada do arquivo', 'Descarta os erros'], answer: 0, explanation: 'Redirecionar é reconectar descritores: o fd 2 passa a apontar para onde o fd 1 aponta naquele instante. Por isso a ordem importa: primeiro §> saida.txt§, depois §2>&1§.' },
  { id: 'lnx-06-e2', type: 'bug', difficulty: 2, points: 10, prompt: 'O disco está em 100% por causa do log do serviço, que **continua rodando e com o arquivo aberto**. O operador executa as linhas abaixo e o espaço não volta. Clique na linha que precisa ser trocada (por um comando que **trunca** o arquivo).', code: '# libera espaço do log do serviço em execução\nrm /var/log/app/app.log\ndf -h /var', answer: 2, explanation: 'Apagar remove só o nome: o serviço mantém o descritor e os dados continuam ocupando espaço (visível como "(deleted)" em §/proc/PID/fd§). Truncar com §: > /var/log/app/app.log§ (ou §truncate -s 0§) libera o espaço sem fechar o descritor.' },
  { id: 'lnx-06-e3', type: 'tf', difficulty: 2, points: 5, prompt: 'Quando um programa recebe sucesso ao gravar em um arquivo, os dados já estão fisicamente no disco.', answer: false, explanation: 'A gravação normalmente vai ao cache de páginas na RAM e é escrita no disco depois. Para garantir durabilidade é preciso §fsync§/§sync§; uma queda de energia antes disso pode perder dados.' },
  { id: 'lnx-06-e4', type: 'match', difficulty: 2, points: 10, prompt: 'Associe cada sintoma ao primeiro comando de diagnóstico.', pairs: [['"No space left on device" com df -h mostrando 40% usado', 'df -i'], ['Espaço não liberou depois de apagar um arquivo grande', 'lsof +L1'], ['"Too many open files" no serviço', 'ls /proc/PID/fd | wc -l'], ['Descobrir qual pasta de /var ocupa mais espaço', 'du -h --max-depth=1 /var']], explanation: 'Cada sintoma tem uma pergunta específica: falta de inodes (§df -i§), arquivos apagados e abertos (§lsof +L1§), vazamento de descritores (contar §/proc/PID/fd§) e maiores consumidores de espaço (§du§).' },
  { id: 'lnx-06-e5', type: 'code', difficulty: 2, points: 20, prompt: 'Implemente §analisarDf(saida, limite = 90)§. O parâmetro é o texto de um §df -h§ (primeira linha é o cabeçalho; colunas: sistema, tamanho, usado, disponível, uso%, ponto de montagem). Devolva um array com os **pontos de montagem** cujo uso seja **maior ou igual** a §limite§, na ordem em que aparecem. Ignore linhas em branco. O ponto de montagem é o texto a partir da sexta coluna (pode ter espaços).', lang: 'javascript', starter: 'function analisarDf(saida, limite = 90) {\n  // seu código aqui\n}\n', hints: ['Pule a primeira linha e divida cada linha por espaços (/\\s+/).', 'parseInt("93%") devolve 93; o ponto de montagem é cols.slice(5).join(" ").'], tests: [{ name: 'filtra por limite padrão', code: "const t = 'Filesystem Size Used Avail Use% Mounted on\\n/dev/sda1 50G 45G 5G 90% /\\n/dev/sdb1 100G 20G 80G 20% /dados\\ntmpfs 2G 2G 0 100% /dev/shm';\nassert.deepEqual(analisarDf(t), ['/', '/dev/shm']);" }, { name: 'limite personalizado', code: "const t = 'Filesystem Size Used Avail Use% Mounted on\\n/dev/sda1 50G 45G 5G 90% /\\n/dev/sdb1 100G 20G 80G 20% /dados';\nassert.deepEqual(analisarDf(t, 20), ['/', '/dados']); assert.deepEqual(analisarDf(t, 95), []);" }, { name: 'ponto de montagem com espaço e linhas em branco', code: "const t = 'Filesystem Size Used Avail Use% Mounted on\\n\\n/dev/sdc1 10G 9G 1G 95% /mnt/meu disco\\n';\nassert.deepEqual(analisarDf(t), ['/mnt/meu disco']);" }], solution: "function analisarDf(saida, limite = 90) {\n  return saida.split('\\n').slice(1).map((l) => l.trim()).filter(Boolean)\n    .map((l) => l.split(/\\s+/))\n    .filter((c) => parseInt(c[4], 10) >= limite)\n    .map((c) => c.slice(5).join(' '));\n}\n", explanation: 'Um alerta de disco nada mais é que um filtro sobre a saída do §df§. Escrever essa lógica em uma linguagem de uso geral facilita testes e evita armadilhas do shell com espaços em nomes.' },
  { id: 'lnx-06-e6', type: 'mc', difficulty: 2, points: 10, prompt: 'Por que o Node.js (e o Nginx) conseguem atender milhares de conexões simultâneas com poucas threads?', options: ['Cada conexão ganha uma thread dedicada, e o hardware moderno aguenta', 'Usam E/S orientada a eventos (epoll no Linux): a thread só trata os descritores que estão prontos', 'Ignoram conexões lentas', 'Mantêm todas as conexões em disco e as processam depois'], answer: 1, explanation: 'Com §epoll§ o kernel avisa quais descritores têm trabalho, então a thread não fica bloqueada em uma conexão ociosa. Funciona muito bem para E/S de rede; trabalho de CPU pesado ainda bloqueia o laço de eventos.' }
],
'lnx-07': [
  { id: 'lnx-07-e1', type: 'mc', difficulty: 1, points: 10, prompt: 'Com §f="meu arquivo.txt"§, o que ocorre ao executar §ls $f§ (sem aspas)?', options: ['Lista o arquivo "meu arquivo.txt" normalmente', 'O shell passa duas palavras ("meu" e "arquivo.txt") ao ls, e ambos "não existem"', 'O shell reclama de sintaxe', 'O ls lista todo o diretório'], answer: 1, explanation: 'Sem aspas, o resultado da expansão é dividido em palavras. O correto é §ls "$f"§. É a causa mais frequente de bugs em shell.' },
  { id: 'lnx-07-e2', type: 'trace', difficulty: 2, points: 10, prompt: 'Rastreie os laços.', code: 'x="a b"\nfor p in $x; do echo "[$p]"; done\nfor p in "$x"; do echo "[$p]"; done', lang: 'bash', steps: [{ q: 'Quantas linhas o primeiro laço imprime?', answers: ['2'] }, { q: 'O que o segundo laço imprime?', answers: ['[a b]'] }], explanation: 'Sem aspas, §$x§ vira duas palavras e o laço roda duas vezes (§[a]§ e §[b]§). Com aspas, a expansão é uma única palavra e imprime §[a b]§.' },
  { id: 'lnx-07-e3', type: 'bug', difficulty: 1, points: 10, prompt: 'O script falha com "nome: command not found". Clique na linha com o erro.', code: '#!/usr/bin/env bash\nset -euo pipefail\nnome = "Ana"\necho "olá, $nome"', answer: 3, explanation: 'Atribuições em shell **não aceitam espaços** em volta do §=§. Com espaços, §nome§ vira um comando com os argumentos §=§ e §Ana§. O correto é §nome="Ana"§.' },
  { id: 'lnx-07-e4', type: 'fill', difficulty: 1, points: 10, prompt: 'Complete a estrutura condicional.', code: 'if grep -q erro log.txt; [[0]]\n  echo "achou"\n[[1]]', answers: [['then'], ['fi']], explanation: '§if lista; then ... fi§: o §if§ testa o **código de saída** do comando (0 = verdadeiro) e o bloco termina com §fi§.' },
  { id: 'lnx-07-e5', type: 'code', difficulty: 3, points: 25, prompt: 'Implemente §parseOpcoes(args)§, que simula §getopts "nk:"§ sobre um array de strings. Devolva §{ n, k, resto }§: §n§ é §true§ se §-n§ foi dado (senão §false§), §k§ é o valor de §-k§ (senão §null§) e §resto§ são os argumentos posicionais. Opções podem vir combinadas (§-nk 5§ equivale a §-n -k 5§). O processamento para no primeiro argumento que não começa com §-§ ou em §--§ (que é consumido). Lance §Error§ para opção desconhecida (§"opção inválida"§) ou §-k§ sem valor (§"falta valor"§).', lang: 'javascript', starter: 'function parseOpcoes(args) {\n  // seu código aqui\n}\n', hints: ['Percorra com um índice i; cada argumento que começa com "-" (e não é "-" nem "--") é um grupo de letras.', 'Para "k", o valor é o restante do grupo ou, se vazio, o próximo argumento.'], tests: [{ name: 'opções separadas e posicionais', code: "assert.deepEqual(parseOpcoes(['-n','-k','5','a','b']), { n: true, k: '5', resto: ['a','b'] });" }, { name: 'sem opções', code: "assert.deepEqual(parseOpcoes([]), { n: false, k: null, resto: [] }); assert.deepEqual(parseOpcoes(['x','y']), { n: false, k: null, resto: ['x','y'] });" }, { name: 'opções combinadas e valor colado', code: "assert.deepEqual(parseOpcoes(['-nk','7','z']), { n: true, k: '7', resto: ['z'] }); assert.deepEqual(parseOpcoes(['-k9']), { n: false, k: '9', resto: [] });" }, { name: 'para no primeiro posicional e em --', code: "assert.deepEqual(parseOpcoes(['a','-n']), { n: false, k: null, resto: ['a','-n'] }); assert.deepEqual(parseOpcoes(['-n','--','-k']), { n: true, k: null, resto: ['-k'] });" }, { name: 'erros', code: "assert.throws(() => parseOpcoes(['-x']), 'opção inválida'); assert.throws(() => parseOpcoes(['-k']), 'falta valor'); assert.throws(() => parseOpcoes(['-nk']), 'falta valor');" }], solution: "function parseOpcoes(args) {\n  const r = { n: false, k: null, resto: [] };\n  let i = 0;\n  while (i < args.length) {\n    const a = args[i];\n    if (a === '--') { i++; break; }\n    if (a.length < 2 || a[0] !== '-') break;\n    for (let j = 1; j < a.length; j++) {\n      const c = a[j];\n      if (c === 'n') r.n = true;\n      else if (c === 'k') {\n        let v = a.slice(j + 1);\n        if (v === '') { i++; if (i >= args.length) throw new Error('falta valor'); v = args[i]; }\n        r.k = v; break;\n      } else throw new Error('opção inválida');\n    }\n    i++;\n  }\n  r.resto = args.slice(i);\n  return r;\n}\n", explanation: 'O §getopts§ segue convenções antigas do Unix: opções agrupadas, valor colado ou no argumento seguinte, e §--§ para encerrar as opções. Reimplementar a lógica ajuda a entender por que o script precisa de §shift $((OPTIND - 1))§ depois do laço.' }
],
'lnx-08': [
  { id: 'lnx-08-e1', type: 'mc', difficulty: 1, points: 10, prompt: 'Quando executa a entrada de cron §30 3 * * 1-5 /opt/bin/backup.sh§?', options: ['A cada 30 minutos, de segunda a sexta', 'Às 03:30, de segunda a sexta', 'Às 03:30 de todos os dias', 'Às 30:03 do primeiro dia do mês'], answer: 1, explanation: 'Os campos são: minuto (30), hora (3), dia do mês (*), mês (*) e dia da semana (1-5 = segunda a sexta).' },
  { id: 'lnx-08-e2', type: 'tf', difficulty: 2, points: 5, prompt: 'O cron executa automaticamente, assim que o servidor volta a ligar, as tarefas agendadas que foram perdidas enquanto ele estava desligado.', answer: false, explanation: 'O cron clássico não recupera disparos perdidos. O timer do systemd com §Persistent=true§ faz isso; ferramentas como §anacron§ também.' },
  { id: 'lnx-08-e3', type: 'match', difficulty: 1, points: 10, prompt: 'Associe cada recurso ao problema que resolve em um script de automação.', pairs: [['mktemp', 'Criar arquivos temporários com nome único e permissão restrita'], ['trap ... EXIT', 'Limpar recursos mesmo se o script falhar'], ['flock -n', 'Impedir duas execuções simultâneas'], ['getopts', 'Processar opções como -n e -k valor']], explanation: 'Quatro práticas de robustez: temporários seguros, limpeza garantida, exclusão mútua e interface de linha de comando previsível.' },
  { id: 'lnx-08-e4', type: 'mc', difficulty: 3, points: 10, prompt: 'No backup, o arquivo temporário é criado **dentro do diretório de destino** e depois renomeado com §mv§. Qual é a principal razão?', options: ['O §mv§ copia o arquivo e valida a integridade', 'A renomeação dentro do mesmo sistema de arquivos é atômica: quem lê vê o backup completo ou nenhum, nunca um arquivo pela metade', 'Diretórios de destino têm mais espaço que /tmp', 'O mktemp só funciona no diretório de destino'], answer: 1, explanation: 'Entre sistemas de arquivos diferentes o §mv§ vira cópia seguida de remoção, que não é atômica. No mesmo sistema, é só atualizar uma entrada de diretório.' },
  { id: 'lnx-08-e5', type: 'code', difficulty: 3, points: 25, prompt: 'Implemente §cronCasa(campo, valor)§, que diz se um **campo** de cron aceita um número. O campo pode ser uma lista separada por vírgulas de itens: §*§ (qualquer), §N§, §A-B§ (intervalo, inclusivo), §*/S§ (a cada S a partir do mínimo 0) e §A-B/S§ (intervalo com passo, começando em A). Devolva §true§ ou §false§. Para §*/S§, considere §valor % S === 0§.', lang: 'javascript', starter: 'function cronCasa(campo, valor) {\n  // seu código aqui\n}\n', hints: ['Separe por "," e faça some() sobre os itens.', 'Para itens com "/", separe o passo; a base é "*" ou "A-B".'], tests: [{ name: 'curinga e número', code: "assert.equal(cronCasa('*', 5), true); assert.equal(cronCasa('5', 5), true); assert.equal(cronCasa('5', 6), false);" }, { name: 'intervalo', code: "assert.equal(cronCasa('1-5', 3), true); assert.equal(cronCasa('1-5', 6), false); assert.equal(cronCasa('1-5', 1), true); assert.equal(cronCasa('1-5', 5), true);" }, { name: 'lista', code: "assert.equal(cronCasa('0,30', 30), true); assert.equal(cronCasa('0,30', 15), false);" }, { name: 'passo', code: "assert.equal(cronCasa('*/15', 30), true); assert.equal(cronCasa('*/15', 31), false); assert.equal(cronCasa('*/15', 0), true);" }, { name: 'intervalo com passo', code: "assert.equal(cronCasa('10-20/5', 15), true); assert.equal(cronCasa('10-20/5', 20), true); assert.equal(cronCasa('10-20/5', 16), false); assert.equal(cronCasa('10-20/5', 25), false); assert.equal(cronCasa('10-20/5', 5), false);" }, { name: 'combinação', code: "assert.equal(cronCasa('1-3,*/20', 40), true); assert.equal(cronCasa('1-3,*/20', 2), true); assert.equal(cronCasa('1-3,*/20', 7), false);" }], solution: "function cronCasa(campo, valor) {\n  return campo.split(',').some((item) => {\n    const [base, passoTxt] = item.split('/');\n    const passo = passoTxt === undefined ? null : Number(passoTxt);\n    let ini = 0, fim = Infinity;\n    if (base !== '*') {\n      if (base.includes('-')) { const [a, b] = base.split('-').map(Number); ini = a; fim = b; }\n      else { ini = fim = Number(base); }\n    }\n    if (valor < ini || valor > fim) return false;\n    return passo ? (valor - (base === '*' ? 0 : ini)) % passo === 0 : true;\n  });\n}\n", explanation: 'Entender a gramática do cron torna as linhas legíveis. Note que §*/15§ é "múltiplos de 15 a partir de 0", e §10-20/5§ é 10, 15 e 20. Uma regra prática: valide expressões com ferramentas (por exemplo, §systemd-analyze calendar§ para timers) antes de agendar.' },
  { id: 'lnx-08-e6', type: 'open', difficulty: 2, points: 15, prompt: 'Você precisa agendar um backup noturno de uma pasta de uploads. Liste os cuidados que o script e o agendamento devem ter para ser confiável.', model: 'Script idempotente com modo de simulação; validação de argumentos; erros em stderr e códigos de saída significativos; arquivo temporário no mesmo diretório e mv ao final (atomicidade); trap para limpar; flock -n para evitar execuções simultâneas; rotação para manter só N backups. Agendamento: caminhos absolutos, PATH definido, saída redirecionada para log (ou timer do systemd com journal e Persistent=true); alertar em caso de falha; testar a restauração periodicamente.', rubric: ['Cita idempotência ou modo de simulação', 'Usa temporário + renomeação atômica e limpeza com trap', 'Evita execução simultânea (flock)', 'Trata o ambiente do cron: caminhos absolutos, PATH e log', 'Prevê alerta de falha e teste de restauração'], explanation: 'A pergunta mistura boas práticas do script e do agendador. Um backup que nunca foi restaurado em teste é apenas uma esperança.' }
],
'lnx-09': [
  { id: 'lnx-09-e1', type: 'mc', difficulty: 2, points: 10, prompt: 'O serviço da empresa ficou fora do ar. Qual é a melhor **primeira** ação de diagnóstico?', options: ['Reiniciar o servidor imediatamente para restabelecer o serviço', 'Coletar evidências (logs, métricas, estado do sistema) antes de qualquer reinício', 'Aplicar chmod -R 777 nos diretórios do serviço', 'Apagar os logs antigos para liberar espaço'], answer: 1, explanation: 'Reiniciar apaga evidências (memória, conexões, processos). Em incidentes reais, às vezes é preciso restaurar o serviço rápido, mas **colete o que for possível antes** e registre o que foi feito. As demais opções agravam o problema.' },
  { id: 'lnx-09-e2', type: 'trace', difficulty: 2, points: 10, prompt: 'Analise a saída e responda.', code: "$ grep 'open files' /proc/4242/limits\nMax open files            1024                 1024                 files\n$ ls /proc/4242/fd | wc -l\n1021", lang: 'bash', steps: [{ q: 'Quantos descritores ainda podem ser abertos antes do erro \"Too many open files\"?', answers: ['3'] }, { q: 'Qual comando mostra quais arquivos e sockets esse processo mantém abertos? (informe só o nome do comando)', answers: ['lsof'] }], explanation: 'O limite é 1024 e já há 1021 em uso: sobram 3. O §lsof -p 4242§ lista o que está aberto e ajuda a decidir se há vazamento (número sempre crescendo) ou limite baixo (número estável perto do teto).' },
  { id: 'lnx-09-e3', type: 'tf', difficulty: 2, points: 5, prompt: 'Se §df -h§ mostra 38% de uso, é impossível receber o erro "No space left on device".', answer: false, explanation: 'O erro também ocorre quando os **inodes** se esgotam (§df -i§) ou quando há cotas. Sempre confira os dois.' },
  { id: 'lnx-09-e4', type: 'match', difficulty: 2, points: 10, prompt: 'Associe cada pergunta de triagem ao comando mais indicado.', pairs: [['O sistema está sobrecarregado? Compare com o número de CPUs', 'uptime'], ['Qual processo escuta a porta 8080?', 'ss -ltnp'], ['O que o serviço registrou nos últimos minutos?', 'journalctl -u serviço --since "10 min ago"'], ['O kernel matou algum processo por falta de memória?', 'journalctl -k']], explanation: 'A triagem usa poucos comandos de leitura: carga (§uptime§), sockets (§ss§), logs do serviço e logs do kernel (§journalctl§).' },
  { id: 'lnx-09-e5', type: 'code', difficulty: 2, points: 20, prompt: 'Implemente §diagnosticar(m)§, que recebe §{ carga1, cpus, memDisponivelPct, discoUsoPct, inodesUsoPct, fdsEmUso, fdLimite }§ e devolve um array de alertas **nesta ordem** (apenas os que se aplicam): §"cpu saturada"§ se §carga1 > cpus§; §"memória baixa"§ se §memDisponivelPct < 10§; §"disco quase cheio"§ se §discoUsoPct >= 90§; §"inodes quase esgotados"§ se §inodesUsoPct >= 90§; §"descritores perto do limite"§ se §fdsEmUso >= 0.8 × fdLimite§. Sem problemas, devolva §[]§.', lang: 'javascript', starter: 'function diagnosticar(m) {\n  // seu código aqui\n}\n', hints: ['Crie o array de alertas e use if para cada regra, na ordem pedida.'], tests: [{ name: 'sistema saudável', code: 'assert.deepEqual(diagnosticar({ carga1: 1.2, cpus: 4, memDisponivelPct: 40, discoUsoPct: 55, inodesUsoPct: 10, fdsEmUso: 100, fdLimite: 1024 }), []);' }, { name: 'um alerta', code: "assert.deepEqual(diagnosticar({ carga1: 1, cpus: 4, memDisponivelPct: 5, discoUsoPct: 55, inodesUsoPct: 10, fdsEmUso: 100, fdLimite: 1024 }), ['memória baixa']);" }, { name: 'vários, na ordem', code: "assert.deepEqual(diagnosticar({ carga1: 9, cpus: 4, memDisponivelPct: 3, discoUsoPct: 95, inodesUsoPct: 91, fdsEmUso: 900, fdLimite: 1024 }), ['cpu saturada', 'memória baixa', 'disco quase cheio', 'inodes quase esgotados', 'descritores perto do limite']);" }, { name: 'limites exatos', code: "assert.deepEqual(diagnosticar({ carga1: 4, cpus: 4, memDisponivelPct: 10, discoUsoPct: 90, inodesUsoPct: 89, fdsEmUso: 80, fdLimite: 100 }), ['disco quase cheio', 'descritores perto do limite']);" }], solution: "function diagnosticar(m) {\n  const a = [];\n  if (m.carga1 > m.cpus) a.push('cpu saturada');\n  if (m.memDisponivelPct < 10) a.push('memória baixa');\n  if (m.discoUsoPct >= 90) a.push('disco quase cheio');\n  if (m.inodesUsoPct >= 90) a.push('inodes quase esgotados');\n  if (m.fdsEmUso >= 0.8 * m.fdLimite) a.push('descritores perto do limite');\n  return a;\n}\n", explanation: 'Uma triagem automatizada é um conjunto de regras simples sobre métricas. Explicitar os limites (inclusive a diferença entre > e >=) evita alertas inconsistentes.' },
  { id: 'lnx-09-e6', type: 'open', difficulty: 3, points: 15, prompt: 'Depois de resolver um incidente de disco cheio causado por logs sem rotação, que itens você incluiria no post-mortem e quais ações preventivas proporia?', model: 'Itens: linha do tempo (início, detecção, ações, resolução); impacto; causa imediata (disco 100%) e causa raiz (logs sem rotação/ausência de alerta); o que funcionou e o que atrasou o diagnóstico. Ações: configurar logrotate (ou limites no journald), alertas de espaço e inodes em 80% e 90%, separar partição de logs, testar a rotação, documentar o procedimento de limpeza (truncar em vez de apagar arquivos abertos) e atribuir responsáveis e prazos.', rubric: ['Inclui linha do tempo e impacto', 'Distingue causa imediata de causa raiz', 'Propõe rotação de logs e alertas de espaço/inodes', 'Atribui ações com responsáveis e prazos ou documenta o procedimento'], explanation: 'O post-mortem sem culpa foca em processos e prevenção, não em pessoas. A causa raiz aqui é a falta de rotação e de alerta, não "alguém deixou o disco encher".' }
]
};

